315	template<int num_bits>
316	std::tuple<at::Tensor, at::Tensor, at::Tensor, at::Tensor, at::Tensor>
317	mha_fwd_kvcache(at::Tensor &q,                       // batch_size x seqlen_q x num_heads x head_size
318	                const at::Tensor &k_pack,                       // batch_size_c x seqlen_k / 4 x num_heads_k x head_size or num_blocks x page_block_size x num_heads_k x head_size if there's a block_table.
319	                const at::Tensor &k_params,                     // batch_size_c x num_groups x num_heads_k x head_size
320	                const at::Tensor &v_pack,                       // batch_size_c x seqlen_k / 4 x num_heads_k x head_size or num_blocks x page_block_size x num_heads_k x head_size if there's a block_table.
321	                const at::Tensor &v_params,                     // batch_size_c x num_groups x num_heads_k x head_size
322	                c10::optional<const at::Tensor> &k_,            // batch_size x seqlen_knew x num_heads_k x head_size
323	                c10::optional<const at::Tensor> &v_,            // batch_size x seqlen_knew x num_heads_k x head_size
324	                c10::optional<const at::Tensor> &seqlens_k_,    // batch_size
325	                at::Tensor &k_pack_new,    
326	                at::Tensor &k_params_new,
327	                at::Tensor &v_pack_new,
328	                at::Tensor &v_params_new,
329	                c10::optional<at::Tensor> &block_table_,        // batch_size x max_num_blocks_per_seq
330	                const float softmax_scale=1.0,
331	                const std::string quant_mode="k-tensor",
332	                const int group_size=128,
333	                const int residual_block_size=128,
334	                const int new_lens=0,
335	                bool is_causal=false,
336	                int window_size_left=-1,
337	                int window_size_right=-1,
338	                const float softcap=0.0,
339	                bool is_rotary_interleaved=true,                // if true, rotary combines indices 0 & 1, else indices 0 & rotary_dim / 2
340	                int num_splits=0
341	                ) {
342	
343	    auto dprops = at::cuda::getCurrentDeviceProperties();
344	    // bool is_sm75 = dprops->major == 7 && dprops->minor == 5;
345	    bool is_sm8x = dprops->major == 8 && dprops->minor >= 0;
346	    bool is_sm90 = dprops->major == 9 && dprops->minor == 0;
347	    TORCH_CHECK(is_sm90 || is_sm8x, "FlashAttention only supports Ampere GPUs or newer.");
348	
349	    CHECK_DEVICE(q); // CHECK_DEVICE(kcache); CHECK_DEVICE(vcache);
350	
351	    at::Tensor block_table;
352	    const bool paged_KV = block_table_.has_value();
353	    if (paged_KV) {
354	        block_table = block_table_.value();
355	        CHECK_DEVICE(block_table);
356	        TORCH_CHECK(block_table.dtype() == torch::kInt32, "block_table must have dtype torch.int32");
357	        TORCH_CHECK(block_table.stride(-1) == 1, "block_table must have contiguous last dimension");
358	    }
359	
360	    auto q_dtype = q.dtype();
361	    const auto sizes = q.sizes();
362	
363	    const int batch_size = sizes[0];
364	    int seqlen_q = sizes[1];
365	    int num_heads = sizes[2];
366	    const int head_size_og = sizes[3]; // dim
367	
368	    const int max_num_blocks_per_seq = !paged_KV ? 0 : block_table.size(1);
369	    const int num_blocks             = !paged_KV ? 0 : v_pack.size(0);
370	    const int page_block_size        = !paged_KV ? 1 : v_pack.size(1);
371	    const int page_block_size_pack   = !paged_KV ? 1 : k_pack.size(1);
372	    const int seqlen_k               = !paged_KV ? v_pack.size(1) : max_num_blocks_per_seq * page_block_size;
373	    const int num_heads_k            = k_pack.size(2);
374	    const int batch_size_c           = !paged_KV ? k_pack.size(0) : batch_size;
375	    TORCH_CHECK(!paged_KV || page_block_size % 256 == 0, "Paged KV cache block size must be divisible by 256");
376	    TORCH_CHECK(batch_size > 0, "batch size must be postive");
377	    TORCH_CHECK(head_size_og <= 256, "FlashAttention forward only supports head dimension at most 256");
378	    TORCH_CHECK(num_heads % num_heads_k == 0, "Number of heads in key/value must divide number of heads in query");
379	
380	    // causal=true is the same as causal=false in this case
381	    if (seqlen_q == 1) { is_causal = false; }
382	
383	    // Faster to transpose q from (b, 1, (nheads_kv ngroups), d) to (b, ngroups, nheads_kv, d) in this case
384	    // H/t Daniel Haziza
385	    const int seqlenq_ngroups_swapped = seqlen_q == 1 && num_heads > num_heads_k && window_size_left < 0 && window_size_right < 0 && head_size_og % 8 == 0;
386	    if (seqlenq_ngroups_swapped) {
387	        const int ngroups = num_heads / num_heads_k;
388	        q = q.reshape({batch_size, num_heads_k, ngroups, head_size_og}).transpose(1, 2);
389	        seqlen_q = ngroups;
390	        num_heads = num_heads_k;
391	    }
392	
393	    CHECK_SHAPE(q, batch_size, seqlen_q, num_heads, head_size_og);
394	    
395	    at::Tensor q_padded, kcache_padded, vcache_padded;
396	    q_padded = q;
397	
398	    at::Tensor out;
399	    out = torch::empty_like(q_padded);
400	
401	    auto round_multiple = [](int x, int m) { return (x + m - 1) / m * m; };
402	    const int head_size = round_multiple(head_size_og, 8);
403	    const int head_size_rounded = round_multiple(head_size, 32);
404	    const int seqlen_q_rounded = round_multiple(seqlen_q, 128);
405	    const int seqlen_k_rounded = round_multiple(seqlen_k, 128);
406	
407	    // Otherwise the kernel will be launched from cuda:0 device
408	    // Cast to char to avoid compiler warning about narrowing
409	    at::cuda::CUDAGuard device_guard{(char)q.get_device()};
410	
411	    auto opts = q.options();
412	
413	    auto softmax_lse = torch::empty({batch_size, num_heads, seqlen_q}, opts.dtype(at::kFloat));
414	
415	    Flash_fwd_params params;
416	    set_params_fprop(params,
417	                     batch_size,
418	                     seqlen_q, seqlen_k,
419	                     seqlen_q_rounded, seqlen_k_rounded,
420	                     num_heads, num_heads_k,
421	                     head_size, head_size_rounded,
422	                     q_padded, 
423	                     kcache_padded, k_pack, k_params,
424	                     vcache_padded, v_pack, v_params,
425	                     out,
426	                     /*cu_seqlens_q_d=*/nullptr,
427	                     /*cu_seqlens_k_d=*/nullptr,
428	                     /*seqused_k=*/nullptr,
429	                     /*p_ptr=*/nullptr,
430	                     softmax_lse.data_ptr(),
431	                     /*p_dropout=*/0.f,
432	                     softmax_scale,
433	                     window_size_left,
434	                     window_size_right,
435	                     softcap,
436	                     quant_mode,
437	                     group_size
438	                     );
439	
440	    at::Tensor k, v;
441	    if (k_.has_value()) {
442	        TORCH_CHECK(v_.has_value(), "If key is supplied, value must also be passed in");
443	        TORCH_CHECK(seqlens_k_.has_value(), "If key is supplied, seqlens_k must also be passed in");
444	
445	        k = k_.value();
446	        v = v_.value();
447	        int seqlen_knew = k.size(1);
448	        auto seqlens_k = seqlens_k_.value();
449	
450	        TORCH_CHECK(k.dtype() == q_dtype, "Key must have the same dtype as query");
451	        TORCH_CHECK(v.dtype() == q_dtype, "Value must have the same dtype as query");
452	        TORCH_CHECK(k.stride(-1) == 1, "Key tensor must have contiguous last dimension");
453	        TORCH_CHECK(v.stride(-1) == 1, "Value tensor must have contiguous last dimension");
454	        CHECK_SHAPE(k, batch_size, seqlen_knew, num_heads_k, head_size_og);
455	        CHECK_SHAPE(v, batch_size, seqlen_knew, num_heads_k, head_size_og);
456	        CHECK_DEVICE(k); CHECK_DEVICE(v);
457	        TORCH_CHECK(seqlens_k.dtype() == torch::kInt32, "seqlens_k must have dtype int32");
458	        CHECK_DEVICE(seqlens_k);
459	        CHECK_CONTIGUOUS(seqlens_k);
460	        CHECK_SHAPE(seqlens_k, batch_size);
461	
462	        params.new_lens          = new_lens;
463	
464	        params.seqlen_knew       = seqlen_knew;
465	        params.knew_ptr          = k.data_ptr();
466	        params.vnew_ptr          = v.data_ptr();
467	        params.knew_batch_stride = k.stride(0);
468	        params.vnew_batch_stride = v.stride(0);
469	        params.knew_row_stride   = k.stride(-3);
470	        params.vnew_row_stride   = v.stride(-3);
471	        params.knew_head_stride  = k.stride(-2);
472	        params.vnew_head_stride  = v.stride(-2);
473	        params.cu_seqlens_k      = static_cast<int *>(seqlens_k.data_ptr());
474	
475	        const int pack_nums = 16 / num_bits;
476	        
477	        params.k_pack_new_ptr            = k_pack_new.data_ptr();
478	        params.k_params_new_ptr          = k_params_new.data_ptr();
479	        params.v_pack_new_ptr            = v_pack_new.data_ptr();
480	        params.v_params_new_ptr          = v_params_new.data_ptr();
481	
482	        params.k_pack_new_batch_stride   = k_pack_new.stride(0);
483	        params.k_params_new_batch_stride = k_params_new.stride(0);
484	        params.v_pack_new_batch_stride   = v_pack_new.stride(0);
485	        params.v_params_new_batch_stride = v_params_new.stride(0);
486	
487	        params.k_pack_new_row_stride     = k_pack_new.stride(-3);
488	        params.k_params_new_row_stride   = k_params_new.stride(-3);
489	        params.v_pack_new_row_stride     = v_pack_new.stride(-3);
490	        params.v_params_new_row_stride   = v_params_new.stride(-1);
491	
492	        params.k_pack_new_head_stride    = k_pack_new.stride(-2);
493	        params.k_params_new_head_stride  = k_params_new.stride(-2);
494	        params.v_pack_new_head_stride    = v_pack_new.stride(-2);
495	        params.v_params_new_head_stride  = v_params_new.stride(-2);
496	
497	        params.k_params_new_dim_stride   = k_params_new.stride(-1);
498	        params.v_params_new_dim_stride   = v_params_new.stride(-3);
499	
500	    }
501	
502	    params.is_seqlens_k_cumulative = !(seqlens_k_.has_value());
503	    params.rotary_dim = 0;
504	
505	    if (paged_KV) {
506	        params.block_table = block_table.data_ptr<int>();
507	        params.block_table_batch_stride = block_table.stride(0);
508	    }
509	    params.page_block_size      = page_block_size;
510	    params.page_block_size_pack = page_block_size_pack;
511	
512	    set_params_splitkv(params, batch_size, num_heads,
513	                       head_size, seqlen_k, seqlen_q,
514	                       head_size_rounded, /*dropout*/0.f, num_splits, dprops, opts);
515	
516	    auto stream = at::cuda::getCurrentCUDAStream().stream();
517	    // Only split kernel supports appending to KV cache, or indexing to the cache with cache_batch_idx,
518	    // or paged KV cache
519	    run_mha_fwd<num_bits>(params, stream, /*force_split_kernel=*/true);  
520	
521	    if (seqlenq_ngroups_swapped) {
522	        out = out.transpose(1, 2).reshape({batch_size, 1, num_heads_k * seqlen_q, head_size_og});
523	    }
524	
525	    return std::make_tuple(out, k_pack_new, k_params_new, v_pack_new, v_params_new);
526	}
