22	// Instances of `Vec` are used to organize groups of >>registers<<, as needed for instance as inputs to tensor core
23	// operations. Consequently, all corresponding index accesses must be compile-time constants, which is why we
24	// extensively use `#pragma unroll` throughout the kernel code to guarantee this.
25	template <typename T, int n>
26	struct Vec {
27	  T elems[n];
28	  __device__ T& operator[](int i) {
29	    return elems[i];
30	  }
31	};
32	
33	
34	using I4 = Vec<int, 4>;
35	
36	// Matrix fragments for tensor core instructions; their precise layout is documented here: 
37	// https://docs.nvidia.com/cuda/parallel-thread-execution/index.html#matrix-fragments-for-mma-m16n8k16-with-floating-point-type
38	using FragA = Vec<half2, 4>;
39	using FragB = Vec<half2, 8>;
40	using FragC = Vec<float, 4>;
41	using FragS = Vec<half2, 1>; // quantization scales
42	
43	
44	// Lookup-table based 3-input logical operation; explicitly used for dequantization as the compiler does not seem to
45	// automatically recognize it in all cases. 
46	template <int lut>
47	__device__ inline int lop3(int a, int b, int c) {
48	  int res;
49	  asm volatile(
50	    "lop3.b32 %0, %1, %2, %3, %4;\n"
51	    : "=r"(res) : "r"(a), "r"(b), "r"(c), "n"(lut)
52	  );
53	  return res;
54	}
55	
56	// Efficiently dequantize an int32 value into a full B-fragment of 4 fp16 values.
57	// We mostly follow the strategy in the link below, with some small changes:
58	// https://github.com/NVIDIA/FasterTransformer/blob/main/src/fastertransformer/cutlass_extensions/include/cutlass_extensions/interleaved_numeric_conversion.h
59	__device__ inline FragA lop3_dequant(int q) {
60	    const int LO = 0x000f000f;
61	    const int HI = 0x00f000f0;
62	    const int EX = 0x64006400;
63	
64	    // Shift right by 8 to now consider elt_45 and elt_67. Issue first to hide RAW dependency if we issue
65	    // immediately before required.
66	    const uint32_t top_i4s = q >> 8;
67	
68	    // Guarantee that the `(a & b) | c` operations are LOP3s.
69	    int lo_1 = lop3<(0xf0 & 0xcc) | 0xaa>(q, LO, EX);        // 0,4
70	    int hi_1 = lop3<(0xf0 & 0xcc) | 0xaa>(q, HI, EX);        // 1,5
71	    int lo_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, LO, EX);  // 2,6
72	    int hi_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);  // 3,7
73	
74	    // We want signed int4 outputs, hence we fuse the `-8` symmetric zero point directly into `SUB` and `ADD`.
75	    const int SUB = 0x64006400; // 0x64086408
76	    const int MUL = 0x2c002c00; // {1/16, 1/16}
77	    const int ADD = 0xd400d400; // 0xd480d480
78	
79	    FragA frag_a;
80	    frag_a[0] = __hsub2(
81	        *reinterpret_cast<half2*>(&lo_1),
82	        *reinterpret_cast<const half2*>(&SUB)
83	    ); // 0,4
84	    frag_a[1] = __hfma2(
85	        *reinterpret_cast<half2*>(&hi_1),
86	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
87	    ); // 1,5
88	    frag_a[2] = __hsub2(
89	        *reinterpret_cast<half2*>(&lo_2),
90	        *reinterpret_cast<const half2*>(&SUB)
91	    ); // 2,6
92	    frag_a[3] = __hfma2(
93	        *reinterpret_cast<half2*>(&hi_2),
94	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
95	    ); // 3,7
96	
97	    return frag_a;
98	}
99	
100	
101	// Efficiently dequantize an int32 value into a full B-fragment of 4 fp16 values.
102	// We mostly follow the strategy in the link below, with some small changes:
103	// https://github.com/NVIDIA/FasterTransformer/blob/main/src/fastertransformer/cutlass_extensions/include/cutlass_extensions/interleaved_numeric_conversion.h
104	__device__ inline FragB lop3_dequant_2bit(int q) {
105	    const int LO = 0x00030003;
106	    const int HI = 0x00300030;
107	    const int EX = 0x64006400;
108	
109	    // Shift right by 8 to now consider elt_45 and elt_67. Issue first to hide RAW dependency if we issue
110	    // immediately before required.
111	    const uint32_t top_i4s = q >> 8;
112	
113	    // Guarantee that the `(a & b) | c` operations are LOP3s.
114	    int lo_1_a = lop3<(0xf0 & 0xcc) | 0xaa>(q, LO, EX);            // 0,8
115	    int lo_1_b = lop3<(0xf0 & 0xcc) | 0xaa>(q >> 2, LO, EX);       // 1,9
116	    int hi_1_a = lop3<(0xf0 & 0xcc) | 0xaa>(q, HI, EX);            // 2,10
117	    int hi_1_b = lop3<(0xf0 & 0xcc) | 0xaa>(q >> 2, HI, EX);       // 3,11
118	    int lo_2_a = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, LO, EX);      // 4,12
119	    int lo_2_b = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s >> 2, LO, EX); // 5,13
120	    int hi_2_a = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);      // 6,14
121	    int hi_2_b = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s >> 2, HI, EX); // 7,15
122	
123	
124	    // int hi_2 = lop3<(0xf0 & 0xcc) | 0xaa>(top_i4s, HI, EX);  // 3,7
125	
126	    // We want signed int4 outputs, hence we fuse the `-8` symmetric zero point directly into `SUB` and `ADD`.
127	    const int SUB = 0x64006400; // {1024, 1024} 0x64086408 
128	    const int MUL = 0x2c002c00; // {1/16, 1/16}
129	    const int ADD = 0xd400d400; // {-64, -64} 0xd480d480 
130	
131	    FragB frag_b;
132	    frag_b[0] = __hsub2(
133	        *reinterpret_cast<half2*>(&lo_1_a),
134	        *reinterpret_cast<const half2*>(&SUB)
135	    ); // 0,8
136	    frag_b[1] = __hsub2(
137	        *reinterpret_cast<half2*>(&lo_1_b),
138	        *reinterpret_cast<const half2*>(&SUB)
139	    ); // 1,9
140	    frag_b[2] = __hfma2(
141	        *reinterpret_cast<half2*>(&hi_1_a),
142	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
143	    ); // 2,10
144	    frag_b[3] = __hfma2(
145	        *reinterpret_cast<half2*>(&hi_1_b),
146	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
147	    ); // 3,11
148	    frag_b[4] = __hsub2(
149	        *reinterpret_cast<half2*>(&lo_2_a),
150	        *reinterpret_cast<const half2*>(&SUB)
151	    ); // 4,12
152	    frag_b[5] = __hsub2(
153	        *reinterpret_cast<half2*>(&lo_2_b),
154	        *reinterpret_cast<const half2*>(&SUB)
155	    ); // 5,13
156	    frag_b[6] = __hfma2(
157	        *reinterpret_cast<half2*>(&hi_2_a),
158	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
159	    ); // 6,14
160	    frag_b[7] = __hfma2(
161	        *reinterpret_cast<half2*>(&hi_2_b),
162	        *reinterpret_cast<const half2*>(&MUL), *reinterpret_cast<const half2*>(&ADD)
163	    ); // 7,15
164	
165	    return frag_b;
