570	    using GmemTileCopyV_Pack = decltype(
571	        make_tiled_copy(Copy_Atom<DefaultCopy, ElementKVPack>{},
572	                        make_layout(make_shape(_64{}, _2{}), make_stride(_2{}, _1{})),
573	                        Layout<Shape<_1, _8>>{}));  // Val layout, 8 vals per store
574	};
575	
